import { TransformNode, SceneLoader, Vector3 } from '@babylonjs/core';
import { applyModelPaint } from '../../../utils/modelPaint.js';

// Player base turret — ORIGINAL mesh (M26 Pershing-inspired), generated by
// scripts/modelgen/player_turret_base.py. Origin at ring center, 'mount' empty
// baked at the trunnion. ringDiameter mirrors ringD in params/player_tank.json.

const PAINT = { paintColor: [0.12, 0.42, 0.88] };

export default {
  id: 'player-turret-base',
  name: 'Player Turret',
  category: 'turret',
  stats: { traverseSpeed: 72 },
  mountEmpty: 'mount',
  defaultCannon: 'player-gun-90mm',
  ringDiameter: 1.95,   // mirrors ringD in scripts/modelgen/params/
  paintColor: PAINT.paintColor,     // composed barrel matches the body color

  async build(scene, paintOverride = null) {
    const result = await SceneLoader.ImportMeshAsync('', '/assets/models/tanks/parts/', 'player_turret_base.glb', scene);
    const mountNode = result.transformNodes.find(n => n.name === this.mountEmpty);
    const mount = mountNode ? mountNode.getAbsolutePosition().clone() : new Vector3(0, 0.34, 1.0);

    const root = new TransformNode('turret_player_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) m.setParent(root);
    for (const m of meshes) m.computeWorldMatrix(true);

    applyModelPaint(meshes, PAINT, scene, paintOverride);
    return { root, meshes, mount };
  },
};
